#include <string>
#include <cmath>

class Solution {
public:
    bool isAdjacentDiffAtMostTwo(std::string s) {
        for (int i = 1; i < (int)s.length(); ++i) {
            if (std::abs(s[i] - s[i - 1]) > 2) return false;
        }
        return true;
    }
};

class Solution {
    public boolean isAdjacentDiffAtMostTwo(String s) {
        for (int i = 1; i < s.length(); i++) {
            if (Math.abs(s.charAt(i) - s.charAt(i - 1)) > 2) return false;
        }
        return true;
    }
}

